// The languages the home page and the ray-tracing guide are published in, the
// same set as the North Pacific Materials site. English is the default: its
// pages have no prefix (/, /ray-tracing); every other language lives under its
// code (/fr, /zh-cn/ray-tracing). /v1 is English only.
//
// This site is a static export, which Next.js's built-in `i18n` routing does
// not support, so each language's pages are generated by pages/[locale]/...
// (see localeStaticPaths) and the language reaches components through
// LocaleContext, not the router.

export const LOCALES = ["en", "fr", "zh-cn", "zh-tw", "ja"] as const;
export type Locale = (typeof LOCALES)[number];
export const DEFAULT_LOCALE: Locale = "en";

// The languages with their own URL prefix
export const PREFIXED_LOCALES = LOCALES.filter((locale): locale is Exclude<Locale, "en"> => locale !== DEFAULT_LOCALE);

// Each language in its own name, for the language switcher
export const LOCALE_LABELS: Record<Locale, string> = {
  en: "English",
  fr: "Français",
  "zh-cn": "简体中文",
  "zh-tw": "繁體中文",
  ja: "日本語",
};

// The switcher's order: English, then Chinese (Kevin's other language), then
// the rest
export const SWITCHER_ORDER: Locale[] = ["en", "zh-tw", "zh-cn", "ja", "fr"];

// BCP 47 tags, for <html lang>, hreflang and Intl
export const LOCALE_TAGS: Record<Locale, string> = {
  en: "en",
  fr: "fr",
  "zh-cn": "zh-CN",
  "zh-tw": "zh-TW",
  ja: "ja",
};

// Open Graph og:locale values
export const OG_LOCALES: Record<Locale, string> = {
  en: "en_CA",
  fr: "fr_CA",
  "zh-cn": "zh_CN",
  "zh-tw": "zh_TW",
  ja: "ja_JP",
};

export const isLocale = (value: unknown): value is Locale => typeof value === "string" && (LOCALES as readonly string[]).includes(value);

// Any value (a page prop, a saved choice) to a known language, English if not
export const toLocale = (value: unknown): Locale => (isLocale(value) ? value : DEFAULT_LOCALE);

// Chinese and Japanese: system CJK fonts and looser line-height (globals.css)
export const isCjkLocale = (locale: Locale): boolean => locale === "zh-cn" || locale === "zh-tw" || locale === "ja";

// A site path in a language: ("fr", "/ray-tracing") -> "/fr/ray-tracing",
// ("fr", "/") -> "/fr", ("en", "/ray-tracing") -> "/ray-tracing". A hash or
// query on the path is kept.
export const localePath = (locale: Locale, path: string): string => {
  if (locale === DEFAULT_LOCALE) return path;
  if (path === "/" || path.startsWith("/#") || path.startsWith("/?")) return `/${locale}${path.slice(1)}`;
  return `/${locale}${path}`;
};

// Pages published in every language: the home page and the ray-tracing guide
// (not /v1, /resources/... or other sites)
export const isLocalizedPath = (href: string): boolean => /^\/(?:$|[#?]|ray-tracing(?:$|[/#?]))/.test(href);

// A link's href in a language: localized pages get the prefix, the rest
// (/v1, the resume, other sites) stay as they are
export const localeHref = (locale: Locale, href: string): string => (isLocalizedPath(href) ? localePath(locale, href) : href);

// The other way: "/fr/ray-tracing" -> "/ray-tracing", "/fr" -> "/"
export const stripLocale = (path: string): string => {
  const match = path.match(/^\/([a-z]{2}(?:-[a-z]{2})?)(?=\/|$|#|\?)/);
  if (!match || !isLocale(match[1]) || match[1] === DEFAULT_LOCALE) return path;
  const rest = path.slice(match[0].length);
  return rest.startsWith("/") ? rest : `/${rest}`;
};

// getStaticPaths for a page under pages/[locale]/: one page per non-default
// language (English is served by the unprefixed page)
export const localeStaticPaths = () => ({
  paths: PREFIXED_LOCALES.map((locale) => ({ params: { locale } })),
  fallback: false as const,
});

// getStaticProps for the same pages: hands the language to _app
export const localeStaticProps = ({ params }: { params?: { locale?: string | string[] } }) => ({
  props: { locale: toLocale(params?.locale) },
});

// Where the switcher remembers the visitor's choice (see LOCALE_SCRIPT)
export const LOCALE_STORAGE_KEY = "locale";

// Called when the visitor picks a language, so their next visit opens in it
export const rememberLocale = (locale: Locale): void => {
  try {
    localStorage.setItem(LOCALE_STORAGE_KEY, locale);
  } catch {
    // Private windows and blocked storage: the choice just isn't remembered
  }
};
